const isDemo=DiversityRuntime.mode==='demo';const storageKey=k=>'ethicity.classroomRetention.'+(isDemo?'demo.':'production.')+k;const sessionStore=DiversityIntegration.storage(globalThis.sessionStorage),localStore=DiversityIntegration.storage(globalThis.localStorage);
