 if(reflectionRound!==round){if(reflectionRound!==null)reflectionDrafts.set(reflectionRound,{a:drafts.reflection,b:drafts.reflection2,dirty:['reflection','reflection2'].filter(k=>editedFields.has(k))});const prior=reflectionDrafts.get(round);drafts.reflection=prior?.a||'';drafts.reflection2=prior?.b||'';for(const k of ['reflection','reflection2'])editedFields.delete(k);for(const k of prior?.dirty||[])editedFields.add(k);reflectionRound=round;}
