function message(s){const text=String(s||'');const authHints={'auth/popup-closed-by-user':'로그인을 취소했습니다. 다시 로그인할 수 있습니다.','auth/popup-blocked':'로그인 창이 차단됐습니다. 브라우저의 팝업 설정을 확인하세요.','auth/unauthorized-domain':'이 주소에서는 로그인할 수 없습니다. 선생님에게 수업 링크를 확인해 주세요.','auth/network-request-failed':'인터넷 연결을 확인하고 다시 시도해 주세요.'};const known=Object.keys(authHints).find(k=>text.includes(k));$('status').textContent=known?authHints[known]:/permission_denied|PERMISSION_DENIED/.test(text)?'접근이 거절되었습니다. 선생님에게 참여 승인과 수업 진행 상태를 확인해 주세요.':/FirebaseError|Client does not have permission|https?:\/\//.test(text)?'연결을 확인하지 못했습니다. 인터넷 연결과 수업 링크를 확인하고 다시 시도해 주세요.':text;}
