  if(adapter){if(isDemo)adapter.db.goOffline();adapter.logout();clearInterval(timer);adapter=null;}
  if(!isDemo&&!authConnection)throw Error('먼저 로그인하세요.');
  const resume=tabSession?await tabSession.prepare(DiversityRuntime.mode,$('room').value.trim(),$('session').value.trim()):null;
  const connection=isDemo?await DiversityConnection.connect(firebase,DiversityRuntime,role,()=>{},'',resume?.uid||null):authConnection;
  const {db,uid}=connection;if(stopPresence){await stopPresence();stopPresence=null;}if(stopConnection){stopConnection();stopConnection=null;}ClassroomMissions.selectContext(targetRoom+'/'+targetSession+'/'+uid);if(role==='student'){selectFormContext(targetRoom+'/'+targetSession+'/'+uid);if(resume?.drafts)for(const key of Object.keys(drafts))if(key!=='drawCount'&&Object.hasOwn(resume.drafts,key)){drafts[key]=resume.drafts[key];editedFields.add(key);}}
